 cs=r['card_scheme']; cr=r['is_credit']=='True'; intra=1. if r['issuing_country']==r['acquirer_country'] else 0.
 return [f for f in F if f['card_scheme']==cs and w(f['account_type'],'R') and w(f['capture_delay'],'<3') and w(f['monthly_fraud_level'],'>8.3%') and w(f['monthly_volume'],'100k-1m') and w(f['merchant_category_code'],5942) and w(f['is_credit'],cr) and w(f['aci'],aci) and w(f['intracountry'],intra)]
