  arr.append((t,aci))
 print(cs,min(arr),arr)
# per transaction min across ACI breakdown scheme/acis
d=collections.defaultdict(float);ch=collections.defaultdict(collections.Counter)
for r in fraudtx:
 arr=[]
 for aci in 'ABCDEFG':
  vals=[f['fixed_amount']+f['rate']*float(r['eur_amount'])/10000 for f in fs(r,aci)]
  arr.append((min(vals) if vals else 0,aci))
 v,a=min(arr);d[r['card_scheme']]+=v;ch[r['card_scheme']][a]+=1
print('\\nper-tx best',dict(d))
for cs,c in ch.items():print(cs,c)
